pping"}], "description": "Students learn to capture soprano and bass frameworks before filling inner detail."}, {"id": "063bb1d6-798f-4b1a-aa57-8ff2f90c6dbc", "type": "subtopic", "title": "Counterpoint hearing", "children": [{"id": "e8e84491-f700-4766-bb88-c9dda9cf8b08", "type": "concept", "title": "Contrary motion"}, {"id": "d6ff0e95-5fc5-4c34-8aac-4868e5c98749", "type": "concept", "title": "Parallel motion"}, {"id": "3363bf70-925c-4785-8c5e-35128e4df33b", "type": "concept", "title": "Suspensions"}, {"id": "6b9fc288-c570-4e08-a395-eda451b80639", "type": "concept", "title": "Voice crossing awareness"}], "description": "Two-part work sharpens intervallic and directional awareness between voices."}]}, {"id": "3b1ed95e-eae6-4369-8d99-100cf37b8825", "type": "topic", "title": "Harmonic Dictation Foundations", "description": "Introduces functional harmonic listening through bass lines, soprano-bass frameworks, cadences, and Roman numeral hearing.", "children": [{"id": "490fd167-283d-4947-9127-a34dd768f4bd", "type": "subtopic", "title": "Bass-line hearing", "children": [{"id": "058b1bd7-63d9-4452-b3cc-f8123426c230", "type": "concept", "title": "Scale-degree bass"}, {"id": "5ac61730-c4a5-407d-b9fe-f05cf0907f72", "type": "concept", "title": "Cadential bass"}, {"id": "9e1c6a87-11cd-41a3-9a4a-52095fce6f29", "type": "concept", "title": "Sequential bass"}, {"id": "bafb6866-3bbe-422c-b788-5529526c3f81", "type": "concept", "title": "Inversion clues"}], "description": "The bass often reveals harmonic direction before full chord quality is clear."}, {"id": "38c499b3-faae-4868-aae0-71cc64a0b437", "type": "subtopic", "title": "Roman numeral listening", "children": [{"id": "eed61c8d-3aab-4f08-a096-1294a4840a09", "type": "concept", "title": "I, IV, V"}, {"id": "ce39022b-3496-4720-ad95-d62739c71e71", "type": "concept", "title": "ii and vi"}, {"id": "cf33329f-84c4-4244-a75b-f5bec407774a", "type": "concept", "title": "Dominant seventh"}, {"id": "6947e23e-5f9b-4614-8e15-e696063f649c", "type": "concept", "title": "Inversions"}], "description": "Students connect heard function to written harmonic labels."}, {"id": "bfdeb269-927f-4908-a4c5-242b1e5a72bc", "type": "subtopic", "title": "Cadential frameworks", "children": [{"id": "66d85e25-fa2a-488f-81a8-796140fb17e8", "type": "concept", "title": "Authentic cadences"}, {"id": "4980c733-5847-4024-96b6-94503c6f81cf", "type": "concept", "title": "Half cadences"}, {"id": "20b750d2-dfbf-4cf0-8f0a-1b4935da74f9", "type": "concept", "title": "Deceptive motion"}, {"id": "710c308c-afd8-4379-a9b1-854d56ad8e1f", "type": "concept", "title": "Cadential six-four intro"}], "description": "Cadences provide anchors for dictation, analysis, and phrase memory."}]}, {"id": "213bb6bc-ff8f-4f08-8cb4-2e69c42943b7", "type": "topic", "title": "Chord Progressions and Phrase-Level Hearing", "description": "Develops recognition of common progressions, harmonic rhythm, phrase models, and structural arrival points.", "children": [{"id": "12862e8a-a50b-4426-ae76-86e394d7fd76", "type": "subtopic", "title": "Common progressions", "children": [{"id": "a8938979-9854-4fd3-acba-4b9bbe51e34a", "type": "concept", "title": "I-IV-V-I"}, {"id": "2e90b6ec-abed-4200-97b9-d6c87ffebe1d", "type": "concept", "title": "ii-V-I"}, {"id": "f9083f6d-50c6-4996-a065-8512f65caa64", "type": "concept", "title": "I-vi-IV-V"}, {"id": "c55a6123-f63f-4751-bcaf-bc1a86d69e97", "type": "concept", "title": "Circle-of-fifths motion"}], "description": "Recognizing progressions helps students hear music in meaningful units instead of isolated chords."}, {"id": "5e05c18c-4873-4adc-be78-038c6df0cb6a", "type": "subtopic", "title": "Harmonic rhythm", "children": [{"id": "85f64079-f7f0-40a8-afad-9c6d126f63cb", "type": "concept", "title": "One chord per bar"}, {"id": "950fbb27-6c9e-4e98-bba2-eba4ebd4837b", "type": "concept", "title": "Accelerated cadences"}, {"id": "58ee01a5-2513-468b-ba32-cb5c002f0bac", "type": "concept", "title": "Prolongation"}, {"id": "ea25f5cf-1847-4d2a-a38e-cc