ertoire."}, {"id": "dc3c12c6-c259-4704-b298-7ea2706ef78c", "type": "subtopic", "title": "Musical continuity", "children": [{"id": "d87a28a8-44f4-422f-8e82-bbb96e7d59d7", "type": "concept", "title": "Steady tempo"}, {"id": "22bc2976-0832-4058-b96b-0c3d68817387", "type": "concept", "title": "Breath planning"}, {"id": "451516a8-8378-4c54-b754-6a1b6e3b81b1", "type": "concept", "title": "Phrase direction"}, {"id": "75c02a15-1cf6-43bb-a256-810e6c855703", "type": "concept", "title": "Recovery after errors"}], "description": "Chromatic accuracy should not break pulse, phrase, or expressive line."}]}, {"id": "cfdb8a92-3b19-4a76-bf14-0e02212a4cf9", "type": "topic", "title": "Complex Rhythms and Meters", "description": "Builds fluency in syncopation, compound subdivision, mixed meters, ties, rests, and rhythmic independence.", "children": [{"id": "a8000eb3-5c63-4da1-9432-adec27120d45", "type": "subtopic", "title": "Subdivision mastery", "children": [{"id": "f0209f71-e66a-4b9f-8c32-303a53ca2bec", "type": "concept", "title": "Sixteenth subdivision"}, {"id": "aba9e015-55f9-439e-bf72-5d58c01a8889", "type": "concept", "title": "Compound division"}, {"id": "be802f2c-a1e6-40c3-846a-f01f2a746dc0", "type": "concept", "title": "Tuplets intro"}, {"id": "283ebc7e-160a-489e-be26-3ebb639167bf", "type": "concept", "title": "Internal counting"}], "description": "Complex rhythm becomes manageable when students feel the smallest active division clearly."}, {"id": "56f78e8b-d377-42f9-9a54-dbafd65ca867", "type": "subtopic", "title": "Syncopation and ties", "children": [{"id": "4db5a336-6824-4a86-ab28-eec4967a0be4", "type": "concept", "title": "Tied notes"}, {"id": "dbcabbf4-e65b-4bea-aabe-bbbe10ef4df1", "type": "concept", "title": "Offbeat accents"}, {"id": "4f976e58-af19-4408-9d4a-109b8e2f99b1", "type": "concept", "title": "Suspensions in rhythm"}, {"id": "66376e90-3de3-468f-bca3-63167fd73fb9", "type": "concept", "title": "Rest patterns"}], "description": "Students learn to sustain pulse through